Lemma carve_succ : forall ws total auser size i, (0 <= i)%Z ->
  carve ws total auser size (Z.to_nat (i + 1)) =
  upd (carve ws total auser size (Z.to_nat i)) (Z.to_nat (total - 1 - i)) (Z_to_bv 64 ((auser + i * size) ≫ 4)).
Proof.
